#include "GameClient/ControlBar.h"
#include "GameClient/CommandButton.h"
#include "Common/INI.h"

void ControlBar::parseCommandButtonDefinition(INI *ini)
{
	AsciiString name(ini->getNextToken());
	CommandButton *button = TheControlBar->findNonConstCommandButton(name);

	if (!button) {
		button = TheControlBar->newCommandButton(name);
		if (ini->getLoadType() == INI_LOAD_CREATE_OVERRIDES)
			button->markAsOverride();
	} else if (ini->getLoadType() == INI_LOAD_RELOAD) {
		// a reload replaces the button: retire the old node, start a fresh one
		if (button->isOverride())
			TheControlBar->rva0031AB77SetFlag();
		TheControlBar->removeCommandButton(button);
		button = TheControlBar->newCommandButton(name);
		button->setReloadState(0);
	} else if (ini->getLoadType() == INI_LOAD_CREATE_OVERRIDES) {
		button = TheControlBar->newCommandButtonOverride(button);
	} else {
		// a repeat definition outside a reload or override: parse it into a scratch button
		CommandButton ignored;
		ini->initFromINI(&ignored, ignored.getFieldParse());
		return;
	}

	ini->initFromINI(button, button->getFieldParse());
}
